create extension if not exists pgcrypto;
create type public.app_role as enum ('admin','trainer','player','viewer');
create type public.card_rarity as enum ('Bronze','Silber','Gold','Ultimate','Legendär');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null default 'Neuer Spieler',username text unique,avatar_path text,created_at timestamptz not null default now());
create table public.user_roles(user_id uuid not null references auth.users(id) on delete cascade,role public.app_role not null default 'player',granted_by uuid references auth.users(id),created_at timestamptz not null default now(),primary key(user_id,role));
create or replace function public.has_role(required_role public.app_role) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=auth.uid() and role=required_role); $$;
create table public.players(id uuid primary key default gen_random_uuid(),display_name text not null,shirt_number int check(shirt_number between 0 and 99),primary_position text not null,image_path text,is_active boolean not null default true);
create table public.seasons(id uuid primary key default gen_random_uuid(),name text not null unique,starts_on date,ends_on date,is_active boolean not null default false);
create table public.matches(id uuid primary key default gen_random_uuid(),season_id uuid references public.seasons(id),opponent text not null,kickoff_at timestamptz,venue text,competition text,home_away text not null default 'home' check(home_away in('home','away')),home_score int check(home_score>=0),away_score int check(away_score>=0),status text not null default 'scheduled' check(status in('scheduled','played','postponed','cancelled')),report text,created_by uuid references auth.users(id));
create table public.match_events(id uuid primary key default gen_random_uuid(),match_id uuid not null references public.matches(id) on delete cascade,player_id uuid references public.players(id),minute int check(minute between 0 and 150),event_type text not null,details text);
create table public.news(id uuid primary key default gen_random_uuid(),title text not null,body text not null,category text not null default 'Verein',status text not null default 'draft' check(status in('draft','published','archived')),published_at timestamptz,created_by uuid references auth.users(id));
create table public.calendar_events(id uuid primary key default gen_random_uuid(),title text not null,event_type text not null,starts_at timestamptz not null,ends_at timestamptz,location text,created_by uuid references auth.users(id));
create table public.attendance_responses(event_id uuid not null references public.calendar_events(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,response text not null check(response in('yes','no','maybe')),updated_at timestamptz not null default now(),primary key(event_id,user_id));
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,body text not null,read_at timestamptz,created_at timestamptz not null default now());
create table public.audit_logs(id bigint generated always as identity primary key,actor_id uuid references auth.users(id),action text not null,entity_type text not null,entity_id text,details jsonb not null default '{}',created_at timestamptz not null default now());
create table public.card_definitions(id uuid primary key default gen_random_uuid(),player_id uuid references public.players(id),display_name text not null,position text not null,overall int not null check(overall between 20 and 99),rarity public.card_rarity not null,pace int not null check(pace between 1 and 99),shooting int not null check(shooting between 1 and 99),passing int not null check(passing between 1 and 99),dribbling int not null check(dribbling between 1 and 99),defense int not null check(defense between 1 and 99),physical int not null check(physical between 1 and 99),edition text not null,image_path text,is_available boolean not null default true);
create table public.card_inventory(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,card_definition_id uuid not null references public.card_definitions(id),upgrade_level int not null default 0 check(upgrade_level between 0 and 3),acquired_at timestamptz not null default now(),locked_by_trade uuid);
create index card_inventory_user_idx on public.card_inventory(user_id);
create table public.club_point_balances(user_id uuid primary key references auth.users(id) on delete cascade,balance bigint not null default 1250 check(balance>=0),updated_at timestamptz not null default now());
create table public.club_point_transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,delta bigint not null check(delta<>0),reason text not null,reference_id uuid,idempotency_key uuid not null,created_at timestamptz not null default now(),unique(user_id,idempotency_key));
create table public.pack_definitions(id uuid primary key default gen_random_uuid(),name text not null unique,price bigint not null check(price>=0),card_count int not null check(card_count between 1 and 10),rarity_weights jsonb not null,is_active boolean not null default false);
create table public.pack_probability_versions(id uuid primary key default gen_random_uuid(),pack_id uuid not null references public.pack_definitions(id),version int not null,rarity_weights jsonb not null,published_at timestamptz not null default now(),unique(pack_id,version));
create table public.pack_openings(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,pack_id uuid not null references public.pack_definitions(id),probability_version_id uuid references public.pack_probability_versions(id),cost bigint not null,idempotency_key uuid not null,created_at timestamptz not null default now(),unique(user_id,idempotency_key));
create table public.pack_opening_items(id uuid primary key default gen_random_uuid(),opening_id uuid not null references public.pack_openings(id) on delete cascade,inventory_id uuid not null references public.card_inventory(id),card_definition_id uuid not null references public.card_definitions(id),rarity public.card_rarity not null);
create table public.ultimate_squads(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,squad_name text not null default 'Meine SVHS-Elf',formation text not null default '1-2-2',is_active boolean not null default false);
create table public.squad_slots(squad_id uuid not null references public.ultimate_squads(id) on delete cascade,slot_number int not null,inventory_id uuid not null references public.card_inventory(id),position text not null,primary key(squad_id,slot_number),unique(squad_id,inventory_id));
create table public.ai_opponents(id uuid primary key default gen_random_uuid(),name text not null,overall int not null check(overall between 20 and 99),difficulty text not null check(difficulty in('easy','normal','hard')),lineup jsonb not null default '[]',is_active boolean not null default true);
create table public.simulated_matches(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,squad_id uuid references public.ultimate_squads(id),opponent_id uuid references public.ai_opponents(id),home_score int not null check(home_score>=0),away_score int not null check(away_score>=0),reward bigint not null default 0 check(reward>=0),idempotency_key uuid not null,completed_at timestamptz not null default now(),unique(user_id,idempotency_key));
create table public.trade_offers(id uuid primary key default gen_random_uuid(),proposer_id uuid not null references auth.users(id) on delete cascade,recipient_id uuid not null references auth.users(id) on delete cascade,status text not null default 'pending' check(status in('pending','accepted','rejected','cancelled','expired')),created_at timestamptz not null default now());
create table public.trade_offer_items(offer_id uuid not null references public.trade_offers(id) on delete cascade,inventory_id uuid not null references public.card_inventory(id),offered_by uuid not null references auth.users(id),primary key(offer_id,inventory_id),unique(inventory_id));
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name','Neuer Spieler'));insert into public.club_point_balances(user_id) values(new.id);insert into public.user_roles(user_id,role) values(new.id,'player');return new;end;$$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security;alter table public.user_roles enable row level security;alter table public.players enable row level security;alter table public.seasons enable row level security;alter table public.matches enable row level security;alter table public.match_events enable row level security;alter table public.news enable row level security;alter table public.calendar_events enable row level security;alter table public.attendance_responses enable row level security;alter table public.notifications enable row level security;alter table public.audit_logs enable row level security;alter table public.card_definitions enable row level security;alter table public.card_inventory enable row level security;alter table public.club_point_balances enable row level security;alter table public.club_point_transactions enable row level security;alter table public.pack_definitions enable row level security;alter table public.pack_probability_versions enable row level security;alter table public.pack_openings enable row level security;alter table public.pack_opening_items enable row level security;alter table public.ultimate_squads enable row level security;alter table public.squad_slots enable row level security;alter table public.ai_opponents enable row level security;alter table public.simulated_matches enable row level security;alter table public.trade_offers enable row level security;alter table public.trade_offer_items enable row level security;
create policy "own profile read" on public.profiles for select to authenticated using(id=auth.uid() or public.has_role('admin'));
create policy "own profile update" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy "own roles read" on public.user_roles for select to authenticated using(user_id=auth.uid() or public.has_role('admin'));
create policy "active players read" on public.players for select to authenticated using(is_active or public.has_role('trainer') or public.has_role('admin'));
create policy "season read" on public.seasons for select to authenticated using(true);create policy "matches read" on public.matches for select to authenticated using(true);create policy "events read" on public.match_events for select to authenticated using(true);
create policy "published news read" on public.news for select to authenticated using(status='published' or public.has_role('trainer') or public.has_role('admin'));
create policy "calendar read" on public.calendar_events for select to authenticated using(true);
create policy "own attendance" on public.attendance_responses for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "own notifications" on public.notifications for select to authenticated using(user_id=auth.uid());
create policy "available cards read" on public.card_definitions for select to authenticated using(is_available or public.has_role('admin'));
create policy "own inventory read" on public.card_inventory for select to authenticated using(user_id=auth.uid() or public.has_role('admin'));
create policy "own CP balance read" on public.club_point_balances for select to authenticated using(user_id=auth.uid() or public.has_role('admin'));
create policy "own CP ledger read" on public.club_point_transactions for select to authenticated using(user_id=auth.uid() or public.has_role('admin'));
create policy "active packs read" on public.pack_definitions for select to authenticated using(is_active or public.has_role('admin'));
create policy "own pack openings read" on public.pack_openings for select to authenticated using(user_id=auth.uid() or public.has_role('admin'));
create policy "own inventory items read" on public.pack_opening_items for select to authenticated using(exists(select 1 from public.pack_openings o where o.id=opening_id and o.user_id=auth.uid()));
create policy "own squads read" on public.ultimate_squads for select to authenticated using(user_id=auth.uid());
create policy "own squad slots read" on public.squad_slots for select to authenticated using(exists(select 1 from public.ultimate_squads s where s.id=squad_id and s.user_id=auth.uid()));
create policy "active opponents read" on public.ai_opponents for select to authenticated using(is_active or public.has_role('admin'));
create policy "own simulated matches read" on public.simulated_matches for select to authenticated using(user_id=auth.uid());
create policy "own trades read" on public.trade_offers for select to authenticated using(proposer_id=auth.uid() or recipient_id=auth.uid());
create policy "trade items participant read" on public.trade_offer_items for select to authenticated using(exists(select 1 from public.trade_offers t where t.id=offer_id and (t.proposer_id=auth.uid() or t.recipient_id=auth.uid())));
-- No direct client writes to currency, inventory, roles or pack outcomes. Add narrowly scoped server RPCs before production.
